    13→typealias EncryptionResetScreenViewModelType = StateStoreViewModelV2<EncryptionResetScreenViewState, EncryptionResetScreenViewAction>
    14→
    15→class EncryptionResetScreenViewModel: EncryptionResetScreenViewModelType, EncryptionResetScreenViewModelProtocol {
    16→    private let clientProxy: ClientProxyProtocol
    17→    private let userIndicatorController: UserIndicatorControllerProtocol
    18→    
    19→    private let actionsSubject: PassthroughSubject<EncryptionResetScreenViewModelAction, Never> = .init()
